/**
 * Check if we have Full Disk Access to read the iMessage database
 */
ipcMain.handle("check-database-access", async () => {
  try {
    const fs = require("fs");

    // Check if file exists and is readable
    if (!fs.existsSync(CHAT_DB_PATH)) {
      return {
        hasAccess: false,
        path: CHAT_DB_PATH,
        error: "Database file not found",
      };
    }

    // Try to get file stats to verify read access
    const stats = fs.statSync(CHAT_DB_PATH);

    return {
      hasAccess: true,
      path: CHAT_DB_PATH,
      fileSize: stats.size,
      lastModified: stats.mtime,
    };
  } catch (error: any) {
    return {
      hasAccess: false,
      path: CHAT_DB_PATH,
      error: error.message,
    };
  }
});

/**
 * Get database statistics (file size, last modified, etc.)
 */
ipcMain.handle("get-database-stats", async () => {
  try {
    const fs = require("fs");
    const stats = fs.statSync(CHAT_DB_PATH);

    return {
      success: true,
      fileSize: stats.size,
      fileSizeMB: (stats.size / (1024 * 1024)).toFixed(2),
      lastModified: stats.mtime.toISOString(),
      path: CHAT_DB_PATH,
    };
  } catch (error: any) {
    return {
      success: false,
      error: error.message,
    };
  }
});

/**
 * Get list of tables in the database
 */
ipcMain.handle("get-database-tables", async () => {
  let db: DatabaseSync | null = null;
  try {
    db = new DatabaseSync(CHAT_DB_PATH, { readOnly: true });

    const tablesQuery = db.prepare(`
      SELECT name, type 
      FROM sqlite_master 
      WHERE type IN ('table', 'view')
      ORDER BY name
    `);

    const tables = tablesQuery.all() as Array<{ name: string; type: string }>;

    return {
      success: true,
      tables,
      totalCount: tables.length,
    };
  } catch (error: any) {
    return {
      success: false,
      error: error.message,
      tables: [],
      totalCount: 0,
    };
  } finally {
    if (db) {
      db.close();
    }
  }
});

/**
 * Open System Preferences to Full Disk Access pane
 */
ipcMain.handle("open-system-preferences", async () => {
  try {
    // Open the Full Disk Access settings pane
    shell.openExternal(
      "x-apple.systempreferences:com.apple.preference.security?Privacy_AllFiles"
    );
    return { success: true };
  } catch (error: any) {
    return {
      success: false,
      error: error.message,
    };
  }
});

/**
 * Helper function to safely convert Apple timestamp (which can be very large) to number
 * Apple timestamps are in nanoseconds since 2001-01-01
 */
function safeTimestampToNumber(timestamp: any): number | null {
  if (timestamp === null || timestamp === undefined) {
    return null;
  }

  // If it's already a number and within safe range, return it
  if (typeof timestamp === "number") {
    return timestamp;
  }

  // If it's a string (from CAST AS TEXT), parse it
  if (typeof timestamp === "string") {
    try {
      // Use BigInt to handle large numbers, then convert to regular number
      const bigIntValue = BigInt(timestamp);
      // Convert to number (may lose precision but that's okay for timestamps)
      return Number(bigIntValue);
    } catch {
      return null;
    }
  }

  // Try parsing as BigInt if it's some other type
  try {
    const bigIntValue = BigInt(timestamp);
    return Number(bigIntValue);
  } catch {
    // Fallback to direct conversion
    return Number(timestamp);
  }
}

/**
 * Helper function to extract text from attributedBody binary data
 * This handles NSAttributedString binary format
 * Based on research from imessage-db-exploration.md and SQL exploration
 *
 * The format stores text as readable UTF-8 strings embedded in the binary data.
 * After "NSString" marker, the actual text content follows.
 */
function extractTextFromAttributedBody(
  attributedBody: Buffer | null
): string | null {
  if (!attributedBody) {
    return null;
  }

  try {
    // Convert buffer to string
    const fullText = attributedBody.toString("utf-8");

    // Remove control characters but keep printable chars, spaces, and newlines
    let cleaned = fullText.replace(
      /[\x00-\x08\x0b-\x0c\x0e-\x1f\x7f-\x9f]/g,
      " "
    );

    // Remove common binary artifacts
    const artifacts = [
      "streamtyped",
      "NSMutableAttributedString",
      "NSAttributedString",
      "NSMutableString",
      "NSString",
      "NSDictionary",
      "NSMutableDictionary",
      "NSObject",
      "NSNumber",
      "NSValue",
      "__kIMMessagePartAttributeName",
      "__kIMBaseWritingDirectionAttributeName",
      "__kIMDataDetectedAttributeName",
      "__kIMOneTimeCodeAttributeName",
    ];

    for (const artifact of artifacts) {
      cleaned = cleaned.replace(new RegExp(artifact, "gi"), "");
    }

    // Remove encoding patterns
    cleaned = cleaned
      .replace(/@\s*\+[A-Za-z0-9,.\-]*\s*/g, "")
      .replace(/\s+iI\s+[^\s]*\s+i\s+\*/g, "")
      .replace(/\s+iI\s+\*/g, "");

    // Find all chunks of readable text (must start with a letter or digit, and be at least 3 chars)
    const chunks: string[] = [];
    const regex = /[A-Za-z0-9][A-Za-z0-9\s\p{P}\p{S}]{2,}/gu;
    let match;

    while ((match = regex.exec(cleaned)) !== null) {
      const chunk = match[0].trim();

      // Filter out very short chunks and chunks that are pure numbers/punctuation
      if (chunk.length >= 3 && /[A-Za-z]/.test(chunk)) {
        chunks.push(chunk);
      }
    }

    if (chunks.length === 0) {
      return null;
    }

    // Join chunks and clean up
    let result = chunks.join(" ");

    // Final cleanup
    result = result
      .replace(/\s+/g, " ") // Multiple spaces to single
      .replace(/\n{3,}/g, "\n\n") // Max 2 consecutive newlines
      .trim();

    // Must have at least some meaningful content
    if (result.length < 2 || !/[A-Za-z]/.test(result)) {
      return null;
    }

    return result;
  } catch (error) {
    console.error("Error extracting text from attributedBody:", error);
    return null;
  }
}

/**
 * Normalize phone number for matching (remove formatting, keep + and digits)
 */
function normalizePhoneNumber(phone: string): string {
  // Remove all non-digit characters except +
  return phone.replace(/[^\d+]/g, "");
}

/**
 * Load all contacts from Contacts app via Swift CLI
 * Uses native Contacts framework - much faster than AppleScript
 */
async function loadContactMap(): Promise<Map<string, string>> {
  // Return existing map if already loaded
  if (contactMap) {
    return contactMap;
  }

  // If already loading, wait a bit and return empty map
  if (contactMapLoading) {
    return new Map();
  }

  contactMapLoading = true;

  try {
    console.log("Loading contacts from Contacts app...");

    // Path to the contacts_dump binary (should be copied by build script)
    const binaryPath = app.isPackaged
      ? path.join(process.resourcesPath, "contacts_dump")
      : path.join(__dirname, "../../contacts_dump");

    // Execute the Swift binary
    const proc = spawn(binaryPath, [], {
      stdio: ["pipe", "pipe", "pipe"],
    });

    let stdout = "";
    let stderr = "";

    proc.stdout.on("data", (data) => {
      stdout += data.toString();
    });

    proc.stderr.on("data", (data) => {
      stderr += data.toString();
    });

    await new Promise<void>((resolve, reject) => {
      proc.on("close", (code) => {
        if (code === 0) {
          resolve();
        } else {
          reject(
            new Error(`contacts_dump exited with code ${code}: ${stderr}`)
          );
        }
      });

      proc.on("error", (err) => {
        reject(err);
      });
    });

    // Parse JSON output
    const jsonData = stdout.trim();
    const map = new Map<string, string>();

    type PersonEntry = { name: string; phones: { numberRaw: string }[] };
    const contacts: PersonEntry[] = JSON.parse(jsonData);

    console.log(`Loaded ${contacts.length} contacts from Contacts app`);

    // Build the map with multiple normalized formats for each phone number
    for (const contact of contacts) {
      const name = contact.name.trim();
      if (!name || name === "Unknown") continue;

      for (const phoneEntry of contact.phones) {
        const phoneRaw = phoneEntry.numberRaw;
        if (!phoneRaw) continue;

        const normalized = normalizePhoneNumber(phoneRaw);

        // Store multiple formats for phone numbers
        map.set(normalized, name);
        if (normalized.startsWith("+")) {
          map.set(normalized.slice(1), name);
        }
        if (normalized.length >= 10) {
          map.set(normalized.slice(-10), name);
        }
        if (normalized.length >= 7) {
          map.set(normalized.slice(-7), name);
        }
      }
    }

    console.log(`Built contact map with ${map.size} phone number mappings`);
    contactMap = map;
    return map;
  } catch (error: any) {
    console.error("Error loading contacts:", error);
    console.error("Error details:", {
      message: error.message,
      code: error.code,
      signal: error.signal,
    });
    // Return empty map on error
    contactMap = new Map();
    return contactMap;
  } finally {
    contactMapLoading = false;
  }
}

/**
 * Load contacts for specific phone numbers
 * Loads the full contact map once, then uses it for lookups
 */
async function loadContactsForNumbers(phoneNumbers: string[]): Promise<void> {
  // If map is already loaded, we don't need to do anything
  if (contactMap) {
    return;
  }

  // Load the full contact map
  const map = await loadContactMap();

  // Cache the lookups
  for (const phone of phoneNumbers) {
    const name = lookupContactName(phone);
    if (name) {
      contactCache.set(phone, name);
    }
  }
}

/**
 * Check if a phone number is valid (not a short code or invalid)
 */
function isValidPhoneNumber(phone: string): boolean {
  const normalized = normalizePhoneNumber(phone);
  // Must be at least 10 digits (US phone number) or have + and be reasonable length
  if (normalized.startsWith("+")) {
    // International: +1XXXXXXXXXX (11 chars minimum) or longer
    return normalized.length >= 11;
  }
  // Domestic: at least 10 digits
  return normalized.length >= 10;
}

/**
 * Look up contact name from phone number or email
 * Uses pre-loaded contact map (must be loaded separately)
 */
function lookupContactName(identifier: string): string | null {
  if (!identifier) return null;

  // Check cache first
  if (contactCache.has(identifier)) {
    return contactCache.get(identifier) || null;
  }

  // Email addresses - return as is for now
  if (identifier.includes("@")) {
    return null;
  }

  // Phone number - check contact map
  if (!contactMap) {
    return null;
  }

  // Try various normalized formats
  const formats = [identifier, normalizePhoneNumber(identifier)];

  const normalized = normalizePhoneNumber(identifier);
  if (normalized.startsWith("+")) {
    formats.push(normalized.slice(1));
  }
  if (normalized.length >= 10) {
    formats.push(normalized.slice(-10));
  }
  if (normalized.length >= 7) {
    formats.push(normalized.slice(-7));
  }

  for (const format of formats) {
    const name = contactMap.get(format);
    if (name) {
      // Cache it
      contactCache.set(identifier, name);
      return name;
    }
  }

  return null;
}

/**
 * Get all unread messages
 * Returns flat list of unread messages ordered by date (newest first)
 */
ipcMain.handle("get-unread-messages", async (_, limit?: number) => {
  let db: DatabaseSync | null = null;
  try {
    db = new DatabaseSync(CHAT_DB_PATH, { readOnly: true });

    // Query for unread messages with related info
    // We'll get the chat identifier and display name for each message
    const query = `
      SELECT 
        m.ROWID,
        m.guid,
        m.text,
        m.attributedBody,
        CAST(m.date AS TEXT) as date,
        m.is_from_me,
        m.handle_id,
        m.service,
        m.cache_has_attachments,
        m.item_type,
        m.is_read,
        CAST(m.date_read AS TEXT) as date_read,
        m.associated_message_guid,
        m.associated_message_type,
        m.associated_message_emoji,
        c.ROWID as chat_id,
        c.chat_identifier,
        c.display_name,
        h.id as handle_identifier
      FROM message m
      INNER JOIN chat_message_join cmj ON m.ROWID = cmj.message_id
      INNER JOIN chat c ON cmj.chat_id = c.ROWID
      LEFT JOIN handle h ON m.handle_id = h.ROWID
      WHERE m.is_read = 0 
        AND m.is_from_me = 0
        AND m.item_type = 0
        AND m.is_finished = 1
        AND m.is_system_message = 0
      ORDER BY m.date DESC
      ${limit ? `LIMIT ${limit}` : ""}
    `;

    const stmt = db.prepare(query);
    const rows = stmt.all() as Array<{
      ROWID: number;
      guid: string;
      text: string | null;
      attributedBody: Buffer | null;
      date: string;
      is_from_me: number;
      handle_id: number | null;
      service: string | null;
      cache_has_attachments: number;
      item_type: number;
      is_read: number;
      date_read: string | null;
      associated_message_guid: string | null;
      associated_message_type: number | null;
      associated_message_emoji: string | null;
      chat_id: number;
      chat_identifier: string;
      display_name: string | null;
      handle_identifier: string | null;
    }>;

    // Collect unique phone numbers from all unread messages
    const phoneNumberSet = new Set<string>();
    const phoneNumberList: Array<{ phone: string; date: number }> = [];

    for (const row of rows) {
      if (row.handle_identifier && !row.handle_identifier.includes("@")) {
        if (isValidPhoneNumber(row.handle_identifier)) {
          phoneNumberSet.add(row.handle_identifier);
          phoneNumberList.push({
            phone: row.handle_identifier,
            date: safeTimestampToNumber(row.date) ?? 0,
          });
        }
      }
    }

    console.log(`Found ${phoneNumberList.length} unique valid phone numbers`);

    // Load contacts only for the specific phone numbers we need
    const numbersToLoad = phoneNumberList
      .filter((item) => !contactCache.has(item.phone))
      .map((item) => item.phone);

    if (numbersToLoad.length > 0) {
      console.log(
        `Loading contacts for ${numbersToLoad.length} new phone numbers...`
      );
      await loadContactsForNumbers(numbersToLoad);
    }

    const messages = rows.map((row) => {
      // Extract text from attributedBody if text is null
      let messageText = row.text;
      if (!messageText && row.attributedBody) {
        messageText = extractTextFromAttributedBody(row.attributedBody);
      }

      return {
        id: String(row.ROWID),
        guid: row.guid,
        text: messageText,
        attributedBody: null, // Don't send binary data to renderer
        date: safeTimestampToNumber(row.date) ?? 0,
        isFromMe: row.is_from_me === 1,
        handleId: row.handle_id ? String(row.handle_id) : null,
        service: row.service,
        cacheHasAttachments: row.cache_has_attachments === 1,
        itemType: row.item_type,
        isRead: row.is_read === 1,
        dateRead: safeTimestampToNumber(row.date_read),
        associatedMessageGuid: row.associated_message_guid,
        associatedMessageType: row.associated_message_type,
        associatedMessageEmoji: row.associated_message_emoji,
        conversationId: String(row.chat_id),
        // Additional fields for display
        chatIdentifier: row.chat_identifier,
        displayName: row.display_name,
        handleIdentifier: row.handle_identifier,
        // Look up contact name (synchronous now - map is pre-loaded)
        contactName: row.handle_identifier
          ? lookupContactName(row.handle_identifier)
          : null,
      };
    });

    return {
      success: true,
      messages,
      count: messages.length,
    };
  } catch (error: any) {
    console.error("Error getting unread messages:", error);
    return {
      success: false,
      error: error.message,
      messages: [],
      count: 0,
    };
  } finally {
    if (db) {
      db.close();
    }
  }
});

/**
 * Get unread messages grouped by conversation/chat
 * Returns conversations with their unread messages
 */
ipcMain.handle("get-unread-conversations", async () => {
  let db: DatabaseSync | null = null;
  try {
    db = new DatabaseSync(CHAT_DB_PATH, { readOnly: true });

    // First, get all chats with unread counts
    const chatStmt = db.prepare(`
      SELECT 
        c.ROWID,
        c.guid,
        c.chat_identifier,
        c.display_name,
        c.style,
        c.service_name,
        CAST(c.last_read_message_timestamp AS TEXT) as last_read_message_timestamp,
        COUNT(DISTINCT m.ROWID) as unread_count,
        CAST(MAX(m.date) AS TEXT) as last_activity
      FROM chat c
      INNER JOIN chat_message_join cmj ON c.ROWID = cmj.chat_id
      INNER JOIN message m ON cmj.message_id = m.ROWID
      WHERE m.is_read = 0
        AND m.is_from_me = 0
        AND m.item_type = 0
        AND m.is_finished = 1
        AND m.is_system_message = 0
      GROUP BY c.ROWID
      ORDER BY MAX(m.date) DESC
    `);

    const chats = chatStmt.all() as Array<{
      ROWID: number;
      guid: string;
      chat_identifier: string;
      display_name: string | null;
      style: number | null;
      service_name: string | null;
      last_read_message_timestamp: string | null;
      unread_count: number;
      last_activity: string;
    }>;

    // Pre-load contacts for all unread messages
    const phoneNumberSet = new Set<string>();
    const phoneNumberList: Array<{ phone: string; date: number }> = [];

    // Get all unread messages to collect phone numbers
    const allMessagesStmt = db.prepare(`
      SELECT DISTINCT
        h.id as handle_identifier,
        CAST(MAX(m.date) AS TEXT) as latest_date
      FROM message m
      INNER JOIN chat_message_join cmj ON m.ROWID = cmj.message_id
      LEFT JOIN handle h ON m.handle_id = h.ROWID
      WHERE m.is_read = 0
        AND m.is_from_me = 0
        AND m.item_type = 0
        AND m.is_finished = 1
        AND m.is_system_message = 0
        AND h.id IS NOT NULL
      GROUP BY h.id
      ORDER BY MAX(m.date) DESC
    `);

    const phoneRows = allMessagesStmt.all() as Array<{
      handle_identifier: string;
      latest_date: string;
    }>;

    for (const row of phoneRows) {
      if (row.handle_identifier && !row.handle_identifier.includes("@")) {
        // Only include valid phone numbers
        if (isValidPhoneNumber(row.handle_identifier)) {
          phoneNumberSet.add(row.handle_identifier);
          phoneNumberList.push({
            phone: row.handle_identifier,
            date: safeTimestampToNumber(row.latest_date) ?? 0,
          });
        }
      }
    }

    console.log(
      `Found ${phoneNumberList.length} unique valid phone numbers from unread messages`
    );

    // Step 2: Check which numbers we need to load (not already in cache)
    const numbersToLoad = phoneNumberList
      .filter((item) => !contactCache.has(item.phone))
      .map((item) => item.phone);

    // Step 3: Load contacts only for the specific phone numbers we need
    if (numbersToLoad.length > 0) {
      console.log(
        `Loading contacts for ${numbersToLoad.length} new phone numbers...`
      );
      await loadContactsForNumbers(numbersToLoad);
    }

    // Step 4: For each chat, get the unread messages
    const conversations = chats.map((chat) => {
      // Get unread messages for this chat
      const messagesStmt = db!.prepare(`
        SELECT 
          m.ROWID,
          m.guid,
          m.text,
          m.attributedBody,
          CAST(m.date AS TEXT) as date,
          m.is_from_me,
          m.handle_id,
          m.service,
          m.cache_has_attachments,
          m.item_type,
          m.is_read,
          CAST(m.date_read AS TEXT) as date_read,
          m.associated_message_guid,
          m.associated_message_type,
          m.associated_message_emoji,
          h.id as handle_identifier
        FROM message m
        INNER JOIN chat_message_join cmj ON m.ROWID = cmj.message_id
        LEFT JOIN handle h ON m.handle_id = h.ROWID
        WHERE cmj.chat_id = ?
          AND m.is_read = 0
          AND m.is_from_me = 0
          AND m.item_type = 0
          AND m.is_finished = 1
          AND m.is_system_message = 0
        ORDER BY m.date DESC
      `);

      const messageRows = messagesStmt.all(chat.ROWID) as Array<{
        ROWID: number;
        guid: string;
        text: string | null;
        attributedBody: Buffer | null;
        date: string;
        is_from_me: number;
        handle_id: number | null;
        service: string | null;
        cache_has_attachments: number;
        item_type: number;
        is_read: number;
        date_read: string | null;
        associated_message_guid: string | null;
        associated_message_type: number | null;
        associated_message_emoji: string | null;
        handle_identifier: string | null;
      }>;

      const unreadMessages = messageRows.map((row) => {
        // Extract text from attributedBody if text is null
        let messageText = row.text;
        if (!messageText && row.attributedBody) {
          messageText = extractTextFromAttributedBody(row.attributedBody);
        }

        return {
          id: String(row.ROWID),
          guid: row.guid,
          text: messageText,
          attributedBody: null,
          date: safeTimestampToNumber(row.date) ?? 0,
          isFromMe: row.is_from_me === 1,
          handleId: row.handle_id ? String(row.handle_id) : null,
          service: row.service,
          cacheHasAttachments: row.cache_has_attachments === 1,
          itemType: row.item_type,
          isRead: row.is_read === 1,
          dateRead: safeTimestampToNumber(row.date_read),
          associatedMessageGuid: row.associated_message_guid,
          associatedMessageType: row.associated_message_type,
          associatedMessageEmoji: row.associated_message_emoji,
          conversationId: String(chat.ROWID),
          chatIdentifier: chat.chat_identifier,
          displayName: chat.display_name,
          handleIdentifier: row.handle_identifier,
          contactName: row.handle_identifier
            ? lookupContactName(row.handle_identifier)
            : null,
        };
      });

      return {
        id: String(chat.ROWID),
        guid: chat.guid,
        chatIdentifier: chat.chat_identifier,
        displayName: chat.display_name,
        style: chat.style,
        serviceName: chat.service_name,
        lastReadMessageTimestamp: safeTimestampToNumber(
          chat.last_read_message_timestamp
        ),
        unreadCount: Number(chat.unread_count),
        lastActivity: safeTimestampToNumber(chat.last_activity) ?? 0,
        unreadMessages,
      };
    });

    const totalUnread = conversations.reduce(
      (sum, conv) => sum + conv.unreadCount,
      0
    );

    return {
      success: true,
      conversations,
      totalUnread,
    };
  } catch (error: any) {
    console.error("Error getting unread conversations:", error);
    return {
      success: false,
      error: error.message,
      conversations: [],
      totalUnread: 0,
    };
  } finally {
    if (db) {
      db.close();
    }
  }
});
